#include <libusb.h>
#include <stdio.h>
int main(void){libusb_device **list;int r=libusb_init(NULL);if(r)return 1;ssize_t n=libusb_get_device_list(NULL,&list);if(n<0){libusb_exit(NULL);return 1;}for(ssize_t i=0;i<n;i++){struct libusb_device_descriptor d;unsigned char p[8];if(libusb_get_device_descriptor(list[i],&d))continue;if(d.idVendor!=0x19d2&&d.idVendor!=0x1782)continue;int depth=libusb_get_port_numbers(list[i],p,8);if(depth<0)continue;printf("%04x:%04x bus=%u ports=",d.idVendor,d.idProduct,libusb_get_bus_number(list[i]));for(int j=0;j<depth;j++)printf("%s%u",j?".":"",p[j]);puts("");struct libusb_config_descriptor *cfg=NULL;if(!libusb_get_active_config_descriptor(list[i],&cfg)){for(int k=0;k<cfg->bNumInterfaces;k++){const struct libusb_interface *f=&cfg->interface[k];for(int j=0;j<f->num_altsetting;j++){const struct libusb_interface_descriptor *a=&f->altsetting[j];printf("interface=%u alt=%u class=%02x subclass=%02x protocol=%02x endpoints=%u\n",a->bInterfaceNumber,a->bAlternateSetting,a->bInterfaceClass,a->bInterfaceSubClass,a->bInterfaceProtocol,a->bNumEndpoints);}}libusb_free_config_descriptor(cfg);}}libusb_free_device_list(list,1);libusb_exit(NULL);return 0;}
